def rotated_binary_search(arr, target):
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2

        # Check if mid is the target
        if arr[mid] == target:
            return mid

        # Determine the rotation point
        if arr[mid] > arr[right]:
            # Target is in the right half
            if target >= arr[mid] and target <= arr[right]:
                left = mid + 1
            else:
                right = mid - 1
        else:
